function verifyPacket(files) {
  const byName = Object.fromEntries(files.map(f => [f.path.split("/").pop(), f]));
  const failures = [];
  const require = (ok, message) => { if (!ok) failures.push(message); };
  for (const [name, file] of Object.entries(byName)) {
    require(!file.error && !file.truncated && typeof file.content === "string", name + ": complete read");
    if (typeof file.content !== "string") continue;
    require(file.content.endsWith("\n"), name + ": final newline");
    require(!/[ \t]+\r?$/m.test(file.content), name + ": trailing whitespace");
    if (name.endsWith(".json")) {
      const value = JSON.parse(file.content);
      require(file.content === JSON.stringify(value, null, 2) + "\n", name + ": canonical two-space JSON");
    }
    if (name.endsWith(".md")) {
      for (const match of file.content.matchAll(/\]\(([^)]+)\)/g)) {
        const target = match[1];
        if (!/^[a-z]+:/.test(target)) require(!!byName[target.split("#")[0]], name + ": local link " + target);
      }
    }
  }
  const authority = JSON.parse(byName["authority.json"].content);
  const result = JSON.parse(byName["result.json"].content);
  const sources = JSON.parse(byName["sources.json"].content);
  require(authority.issue.key === "integration-policy" && authority.issue.number === 26, "assigned issue identity");
  require(authority.issue.primaryCommandId === 40751, "reserved command identity");
  require(result.baseline === authority.baseline, "baseline identity");
  require(result.issueKey === authority.issue.key && result.issueUrl === authority.issue.url, "result issue identity");
  require(result.nativeAcceptance === "OPEN" && authority.nativeAcceptance === "OPEN", "native acceptance open");
  require(authority.ownerApproval.status === "NOT_RECORDED_IN_READ_AUTHORITY", "no invented approval");
  require(result.dependencies.length === authority.issue.blocked.length, "declared dependency parity");
  require(result.remainingCriteria.length === authority.issue.accept.length, "every criterion retains explicit open state");
  require(Object.values(result.platformStates).every(x => x === "OPEN_UNRUN"), "all target platforms unrun");
  require(result.evidencePaths.every(x => !!byName[x]), "all evidence paths exist");
  require(sources.localFiles.every(x => /^[0-9a-f]{64}$/.test(x.sha256)), "source identities are SHA-256");
  require(sources.localFiles.filter(x => x.role === "read-only native source").every(x => x.resultSha256 === x.sha256), "native base/result equality");
  if (failures.length) throw new Error(failures.join("\n"));
  return { status: "PASS", coverage: "JSON syntax/format, final newlines, whitespace, local links, issue/baseline/command identity, all acceptance criteria, evidence paths, source identity format and OPEN native states" };
}
